    # f[i] - f[i-1] is always 0 or 1, so there are 2^N states.
    states = []
    state_id = {}
    for mask in range(1 << N):
        f = [0] * (N + 1)
        cur = 0
        for i in range(1, N + 1):
            if (mask >> (i - 1)) & 1:
                cur += 1
            f[i] = cur
        t = tuple(f)
        state_id[t] = len(states)
        states.append(t)

    # Precompute transitions, grouping characters that lead to the same state.
    trans = []
    for f in states:
        cnt = {}
        for c in range(26):
            new = [0] * (N + 1)
            for i in range(1, N + 1):
                best = f[i]
                if new[i - 1] > best:
                    best = new[i - 1]
                if s_codes[i - 1] == c:
                    cand = f[i - 1] + 1
                    if cand > best:
                        best = cand
                new[i] = best
            nid = state_id[tuple(new)]
            cnt[nid] = cnt.get(nid, 0) + 1
        trans.append(list(cnt.items()))

    nstates = len(states)
    dp = [0] * nstates
    dp[0] = 1  # empty processed prefix

    for _ in range(M):
        ndp = [0] * nstates
        for i, v in enumerate(dp):
            if v:
                for j, m in trans[i]:
                    ndp[j] += v * m
        dp = [x % MOD for x in ndp]

    ans = [0] * (N + 1)
    for i, v in enumerate(dp):
        if v:
            k = states[i][N]
            ans[k] = (ans[k] + v) % MOD

    print(" ".join(map(str, ans)))

