class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        positions = {}

        for i, value in enumerate(nums):
            positions.setdefault(value, []).append(i)

        answer = [-1] * n

        for indices in positions.values():
            m = len(indices)
            if m == 1:
                continue

            for pos, idx in enumerate(indices):
                prev_idx = indices[pos - 1]
                next_idx = indices[(pos + 1) % m]

                dist_prev = abs(idx - prev_idx)
                dist_prev = min(dist_prev, n - dist_prev)

                dist_next = abs(idx - next_idx)
                dist_next = min(dist_next, n - dist_next)

                answer[idx] = min(dist_prev, dist_next)

