class Solution:
    def findMaxSum(self, nums1: List[int], nums2: List[int], k: int) -> List[int]:
        n = len(nums1)
        ans = [0] * n

        if k == 0:
            return ans

        order = sorted(range(n), key=lambda idx: nums1[idx])

        heap = []
        total = 0
        i = 0

        while i < n:
            value = nums1[order[i]]
            j = i

            while j < n and nums1[order[j]] == value:
                j += 1

            for p in range(i, j):
                ans[order[p]] = total

