class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        NEG = -10**18

        # prev[i] = maximum sum using the current number of subarrays
        # within nums[:i]. Initially, 0 subarrays have sum 0 for every prefix.
        prev = [0] * (n + 1)

        for _ in range(k):
            cur = [NEG] * (n + 1)
            best = NEG

            for i in range(1, n + 1):
                val = cur[i - 1]

                # A new subarray ending at i-1 can start at any j <= i - m.
                j = i - m
                if j >= 0:
                    pv = prev[j]
                    if pv != NEG:
                        candidate_best = pv - prefix[j]
                        if candidate_best > best:
                            best = candidate_best

                if best != NEG:
                    candidate = prefix[i] + best
                    if candidate > val:
                        val = candidate

                cur[i] = val

            prev = cur

        return prev[n]
