class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        from functools import lru_cache

        def count_up_to(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            length = len(digits)

            pow10 = [1] * (length + 1)
            for i in range(1, length + 1):
                pow10[i] = pow10[i - 1] * 10

            @lru_cache(maxsize=None)
            def dfs(pos: int, tight: bool, started: bool, digit_sum: int, product: int) -> int:
                # Once a zero has appeared after the number has started,
                # the product is 0, so every completion is beautiful.
                if not tight and started and product == 0:
                    return pow10[length - pos]

                if pos == length:
                    if not started:
                        return 0
                    return 1 if product % digit_sum == 0 else 0

                limit = digits[pos] if tight else 9
                total = 0

                for d in range(limit + 1):
                    next_tight = tight and d == digits[pos]

                    if not started:
                        if d == 0:
                            total += dfs(pos + 1, next_tight, False, digit_sum, product)
                        else:
                            total += dfs(pos + 1, next_tight, True, digit_sum + d, product * d)
                    else:
                        next_product = 0 if d == 0 else product * d
                        total += dfs(pos + 1, next_tight, True, digit_sum + d, next_product)

                return total

            return dfs(0, True, False, 0, 1)

        return count_up_to(r) - count_up_to(l - 1)
