class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        edges = []
        for i, (x, y) in enumerate(conflictingPairs):
            if x > y:
                x, y = y, x
            edges.append((y, x, i))  # (right endpoint, left endpoint, original index)

        edges.sort()

        m = len(edges)
        gain = [0] * m

        total = 0

        max_left = 0
        max_count = 0
        second_left = 0
        unique_id = -1

        ptr = 0

        for r in range(1, n + 1):
            while ptr < m and edges[ptr][0] == r:
                left = edges[ptr][1]
                idx = edges[ptr][2]
                ptr += 1

                if left > max_left:
                    second_left = max_left
                    max_left = left
                    max_count = 1
                    unique_id = idx
                elif left == max_left:
                    max_count += 1
                    if max_count == 2:
                        unique_id = -1
                else:
                    if left > second_left:
                        second_left = left

            total += r - max_left

            if max_count == 1:
                gain[unique_id] += max_left - second_left

        return total + (max(gain) if m else 0)
