class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def get_substrings(x: str):
            n = len(x)
            subs = {x[i:j] for i in range(n + 1) for j in range(i, n + 1)}
            return sorted(
                ((sub, len(sub)) for sub in subs),
                key=lambda item: item[1],
                reverse=True
            )

        subs_s = get_substrings(s)
        subs_t = get_substrings(t)

        ans = 0
        max_t_len = subs_t[0][1] if subs_t else 0
        max_possible = len(s) + len(t)

        for a, la in subs_s:
            if la + max_t_len <= ans:
                break

            for b, lb in subs_t:
                total = la + lb
                if total <= ans:
                    break

                candidate = a + b
                if candidate == candidate[::-1]:
                    ans = total
                    if ans == max_possible:
                        return ans

        return ans
