class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        events = []
        total_area = 0

        for _, y, l in squares:
            events.append((y, l))          # square starts contributing
            events.append((y + l, -l))     # square stops contributing
            total_area += l * l

        events.sort()

        # We need the first y where 2 * area_below(y) >= total_area.
        target2 = total_area

        prev = events[0][0]
        below = 0       # exact area below the current coordinate
        slope = 0       # total width of squares active on the next interval
        i = 0
        n = len(events)

        while i < n:
            cur = events[i][0]

            if cur > prev:
                # If the target was already reached at prev, prev is the minimum.
                if 2 * below >= target2:
                    return float(prev)

                below_cur = below + slope * (cur - prev)

                # If the target is reached inside (prev, cur], solve linearly.
                if 2 * below_cur >= target2:
                    if slope == 0:
                        return float(prev)
                    return float(prev + (target2 - 2 * below) / (2 * slope))

                below = below_cur

            # Apply all events at this y-coordinate.
            delta = 0
            while i < n and events[i][0] == cur:
                delta += events[i][1]
                i += 1

            slope += delta
            prev = cur

        return float(prev)
