    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10**15 + 1

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(CAP, fact[i - 1] * i)

        odd_count = (n + 1) // 2
        even_count = n // 2

        base = min(CAP, fact[odd_count] * fact[even_count])
        total = base if n % 2 == 1 else min(CAP, base * 2)

        if total < k:
            return []

        used = [False] * (n + 1)
        rem_odd = odd_count
        rem_even = even_count
        ans = []

        for pos in range(n):
            if pos == 0:
                if n % 2 == 1:
                    candidates = [x for x in range(1, n + 1, 2) if not used[x]]
                else:
                    candidates = [x for x in range(1, n + 1) if not used[x]]
            else:
                required_parity = 1 - (ans[-1] % 2)
                if required_parity == 1:
                    candidates = [x for x in range(1, n + 1, 2) if not used[x]]
                else:
                    candidates = [x for x in range(2, n + 1, 2) if not used[x]]

            chosen = None
            for cand in candidates:
                if cand % 2 == 1:
                    count = min(CAP, fact[rem_odd - 1] * fact[rem_even])
                else:
                    count = min(CAP, fact[rem_odd] * fact[rem_even - 1])

                if k > count:
                    k -= count
                else:
                    chosen = cand
                    break

            if chosen is None:
                return []

            ans.append(chosen)
            used[chosen] = True

            if chosen % 2 == 1:
                rem_odd -= 1
            else:
                rem_even -= 1

        return ans
